select jsonb_build_object(
'policies',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'public' else pg_get_userbyid(r) end) from unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid where c.relnamespace='public'::regnamespace and c.relname in ('allowance_rules','bills','budgets','financial_accounts','transactions','savings_goals') and p.polcmd in ('a','w','d','*')),
'grants',(select jsonb_agg(jsonb_build_object('table',t,'role',r,'insert',has_table_privilege(r,'public.'||t,'INSERT'),'update',has_table_privilege(r,'public.'||t,'UPDATE'),'delete',has_table_privilege(r,'public.'||t,'DELETE'))) from unnest(array['allowance_rules','bills','budgets','financial_accounts','transactions','savings_goals']) t cross join unnest(array['anon','authenticated']) r),
'anonInheritsAuthenticated',pg_has_role('anon','authenticated','MEMBER'),
'helpers',(select jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid))) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('is_family_member','can_manage_family') and p.prokind='f')) as review;
